def sum_n(n):
    total = 0
    for i in range(n):
        total += i
    return total

print(sum_n(5))

def max_memory_example(n):
    data = list(range(n))
    return len(data)

print(max_memory_example(100000))

def save_and_load(filename, text):
    with open(filename, "w", encoding="utf-8") as f:
        f.write(text)
    with open(filename, "r", encoding="utf-8") as f:
        return f.read()

print(save_and_load("demo.txt", "持久化"))

import threading

def worker(name):
    print(name)

threads = []
for i in range(2):
    t = threading.Thread(target=worker, args=(f"T{i}",))
    threads.append(t)
    t.start()
for t in threads:
    t.join()

