import socket

# 演示 DNS 解析：把域名解析为 IP 地址
def resolve(host):
    try:
        ip = socket.gethostbyname(host)
        print(f"{host} -> {ip}")
    except socket.gaierror as e:
        print(f"解析失败: {e}")


resolve("www.baidu.com")
resolve("google.com")

